def shapley_credit(agents, value_fn, n_samples=1000):
    perms = [random.sample(agents, len(agents)) for _ in range(n_samples)]
    marginal = {a: 0 for a in agents}
    for p in perms:
        prev = value_fn([])
        for a in p:
            cur = value_fn(p[:p.index(a)+1])
            marginal[a] += cur - prev
            prev = cur
    return {a: m/n_samples for a, m in marginal.items()}
